  "artifact_type": "series_a_pitch_deck",
  "company_name": "Sora (formerly Project Hominid)",
  "tagline": "Infinite Visual Feedstock for the Post-Attention Economy",
  "slides": {
    "slide_1_the_problem": {
      "heading": "Content is Finite. The Appetite for Plausibility is Infinite.",
      "bullet_points": [
        "Traditional production bottlenecks limit output.",
        "Audiences churn when visual novelty drops.",
        "Generative models fail due to lack of diverse, cleared training data."
      ]
    },
    "slide_2_the_insight": {
      "heading": "The Sasquatch Protocol",
      "text": "Our Beta test (a viral cryptid series generating 400M+ impressions) proved audiences engage primarily with 'ambient plausibility' rather than narrative truth. They want the feeling of reality, optimized for friction-free consumption."
    },
    "slide_3_the_moat": {
      "heading": "The Rights Stack",
      "text": "We aren't scraping the internet. We bought the basement.",
      "assets_acquired": [
        "14 bankrupt stock footage libraries",
        "Orphaned 1990s local TV broadcast archives",
        "De-indexed commercial b-roll",
        "Public domain surveillance textures"
      ]
    },
    "slide_4_the_product": {
      "heading": "The Slop Engine",
      "text": "A proprietary generative model trained entirely on our legally cleared 'visual junk-data' archive. We don't make movies. We generate the infinite adjacent-content that fills the gaps between human attention."
    },
    "slide_5_ask": {
      "heading": "$500M to Automate Reality",
      "text": "Funding will be used to ingest the remaining 40% of distressed global media assets and scale our inference compute."
    }
  }
}

